@Service
@Transactional(readOnly = true)              // thêm từ đầu để mọi method đọc nhanh hơn
class CustomerService {

    public CustomerView find(long id) { ... }

    @Transactional                          // method ghi cũ được khai báo riêng
    public void changePhone(long id, String phone) { ... }

    public void changeAddress(long id, AddressRequest req) {   // method mới, quên annotation
        Customer customer = customers.findById(id).orElseThrow();
        customer.moveTo(req.line(), req.city());
        customers.save(customer);
    }
}

